Var
i : Integer;
begin
  for i := 0 to ComponentCount -1 do
  if Components[i] is TEdit then
  begin
     TEdit(Components[i]).Text := '';
  end;
  for i := 0 to ComponentCount -1 do
  if Components[i] is TMemo then
  begin
     TMemo(Components[i]).lines.Clear;
